export const hasVendorMark = (vendor: string): boolean => vendor in MARKS;

export const isVendorMarkColored = (vendor: string): boolean =>
  MARKS[vendor]?.colorBody != null;

export interface VendorIconProps extends Omit<SVGProps<SVGSVGElement>, "name"> {
  vendor: string;
  /** Shown in the letter fallback when a vendor has no published mark. */
  label?: string;
  /**
   * Force the monochrome treatment. Used in chart legends, where a coloured
   * swatch beside the mark already carries the series mapping -- a brand colour
   * next to a different series colour reads as a contradiction.
   */
  mono?: boolean;
}

/**
 * A vendor brand mark. Falls back to a lettered square ONLY for a vendor with no
 * published logo -- never as a shortcut for one we simply have not wired up.
 */
export function VendorIcon({ vendor, label, mono, className, ...rest }: VendorIconProps) {
  const mark = MARKS[vendor];
  if (!mark) {
    const letter = (label ?? vendor ?? "?").trim().charAt(0).toUpperCase() || "?";
    return (
      <span
        aria-hidden
        className={cn(
          "inline-flex size-[1em] shrink-0 items-center justify-center rounded-[3px]",
          "border border-current/25 text-[0.62em] leading-none font-semibold",
          className,
        )}
      >
        {letter}
      </span>
    );
  }
  // A coloured mark paints itself; forcing fill=currentColor would flatten it.
  const paintSelf = mark.colorBody != null && !mono;
  const draw = (body: string, self: boolean, extra?: string) => (
    <svg
      viewBox={mark.viewBox}
      width="1em"
      height="1em"
      {...(self ? {} : { fill: "currentColor" })}
      {...(mark.fillRule ? { fillRule: mark.fillRule as "evenodd" | "nonzero" } : {})}
      aria-hidden
      focusable="false"
      className={cn("inline-block size-[1em] shrink-0", extra, className)}
      dangerouslySetInnerHTML={{ __html: body }}
      {...rest}
    />
  );

  /*
   * A mark that only reads on one background renders BOTH treatments, swapped by
   * CSS rather than by JavaScript. The theme is a class on <html> set before the
   * first paint, so a CSS swap is right on the very first frame -- reading the
   * theme in JS would flash the wrong mark on every load.
   */
  if (paintSelf && mark.colorIn && mark.colorIn !== "both") {
    const colorOnDark = mark.colorIn === "dark";
    return (
      <>
        {draw(mark.colorBody!, true, colorOnDark ? "hidden dark:inline-block" : "dark:hidden")}
        {draw(mark.body, false, colorOnDark ? "dark:hidden" : "hidden dark:inline-block")}
      </>
    );
  }

  return draw(paintSelf ? mark.colorBody! : mark.body, paintSelf);
}
